import os, sys, json, gzip, base64

print()
print("=" * 55)
print("  نصب فروشگاه قطعات دوربین مداربسته")
print("=" * 55)
print()

# داده‌های پروژه (فشرده شده)
DATA = """"""

def write_file(path, content):
    path = path.replace('/', os.sep).replace('\\', os.sep)
    os.makedirs(os.path.dirname(path) if os.path.dirname(path) else '.', exist_ok=True)
    with open(path, 'w', encoding='utf-8', newline='\n') as f:
        f.write(content)

print("در حال آماده‌سازی فایل‌ها...")
raw = gzip.decompress(base64.b64decode(DATA))
files = json.loads(raw.decode('utf-8'))

print(f"تعداد فایل‌ها: {len(files)}")
print()

for i, (path, content) in enumerate(files.items(), 1):
    write_file(path, content)
    if i % 10 == 0:
        print(f"  {i}/{len(files)} فایل ساخته شد...")

print(f"\n✓ همه {len(files)} فایل ساخته شد!")
print()
